contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 seed) public {
        // Use a random seed to influence block.timestamp and block.difficulty (cheatcodes not available, so we just use seed as msg.value stub, but need TICKET_AMOUNT = 10)
        // Actually, we need to call play() with exactly 10 wei. So we use assume and deal.
        vm.deal(address(this), 10);
        // Record pot before
        uint256 potBefore = c.pot();
        // Call play()
        (bool success, ) = address(c).call{value: 10}(abi.encodeWithSignature("play()"));
        // Only consider successful calls where the random outcome might be 0; we can't control randomness, so we check after call.
        if (success) {
            uint256 potAfter = c.pot();
            // If the player won (random == 0), pot should be 0 because it was reset after payout.
            // But we cannot directly know if random was 0. However, the invariant we want: AFTER any successful call, the pot should be either unchanged (if random==1) OR reset to 0 (if random==0).
            // Actually, if random==1, pot increases by 10; if random==0, pot becomes 0. So the only case where pot becomes 0 is when random==0.
            // But the property we want to catch is that in the buggy version, after random==0, pot is NOT reset to 0. So we need to assert that the pot never holds a value > 0 that is less than potBefore+10? No simpler is: after any successful play, if the pot is not the previous pot+10, it must be 0.
            assert(potAfter == 0 || potAfter == potBefore + 10);
        } else {
            // If revert, do nothing
        }
    }
}

