import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 seed) public {
        // Set the block timestamp and difficulty to influence the random outcome
        vm.warp(seed);
        vm.difficulty(seed);

        uint256 ticket = 10;
        // Ensure the player has enough ether
        vm.deal(address(this), ticket);

        // Call play() with exactly TICKET_AMOUNT
        (bool success, ) = address(c).call{value: ticket}(abi.encodeWithSignature("play()"));

        // The rule: after a successful play(), if the random outcome is 0 (win), then pot must be 0.
        // Since we cannot directly observe the random outcome, we use the fact that if the outcome was 0,
        // the pot becomes 0 in the reference; otherwise it remains 10.
        // But the buggy version never resets pot when outcome is 0, so pot will be 10 even on win.
        // This implies that the invariant "pot is always 0 or 10 after one play" still holds for both.
        // However, the difference is: on a win, pot should be 0, but the bug leaves it at 10.
        // We can encode this by checking that pot == 0 whenever the player receives a transfer > 0.
        // That requires observing the player's balance change. Let's do that.

        // Re-call with a known player account
        address player = address(0x1234);
        vm.deal(player, ticket);
        uint256 balanceBefore = player.balance;
        vm.prank(player);
        (bool success2, ) = address(c).call{value: ticket}(abi.encodeWithSignature("play()"));
        uint256 balanceAfter = player.balance;
        bool receivedPayout = balanceAfter > balanceBefore;

        // If the player received a payout (win), then pot must be 0
        if (receivedPayout) {
            assertTrue(c.pot() == 0, "Pot should be zero after a win");
        }
    }
}

