import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property() public {
        // Simulate that the player always wins (random == 0)
        // We cannot control random, but we can call play() and check the invariant
        // that after a win, pot must be zero.
        // Use vm.roll and vm.warp to try to influence random, but this is not reliable.
        // Instead, we consider that any call that results in random == 0 leaves pot == 0.
        // Since we cannot know which calls win, we make multiple calls and expect
        // that if at any point pot != 0, then random must be 1 (player lost).
        // The formal rule: after any play() call, pot == 0 OR pot == TICKET_AMOUNT + previous pot - FEE (but that's not general).
        // Better: after play(), pot must be either 0 or pot == TICKET_AMOUNT + msg.value before call (but tricky).
        // Actually, the simplest general rule: pot is never increased by more than TICKET_AMOUNT per call.
        // But to catch the bug: after a win (random==0), pot must be 0.
        // Since we cannot force random, we use the property:
        // The variable pot can never be strictly between 0 and TICKET_AMOUNT after a call.
        // Because if random==0, pot becomes 0; if random==1, pot becomes previous pot + TICKET_AMOUNT.
        // Bug: after random==0, pot becomes previous pot + TICKET_AMOUNT - FEE, which is >0 if previous pot was 0.
        uint256 potBefore = c.pot();
        c.play{value: 10}();
        uint256 potAfter = c.pot();
        // After play(), either pot==0 (win), or pot == potBefore + 10 (loss).
        assertTrue(potAfter == 0 || potAfter == potBefore + 10);
    }
}

