pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 seed) public {
        // Seed to influence random outcome; we need the case where player wins (random == 0)
        // We cannot control the random, so we just call play() and check after each call
        // The property must hold for all calls: after play(), if the caller wins, pot is zero.
        // We'll capture the caller's balance before and after to infer win/loss.
        // But simpler: we assert that after any play() call, pot is either 0 or TICKET_AMOUNT (10) if player loses.
        // However, the bug leaves pot = pot - FEE_AMOUNT when player wins, so pot != 0.
        // So we assert a general rule: after any play(), either pot == 0 or (pot >= TICKET_AMOUNT and pot == previousPot + TICKET_AMOUNT).
        // Actually, the simplest direct rule is: after play(), the pot is either 0 (if win) or previousPot + TICKET_AMOUNT (if lose).
        // Since we cannot know which case, we can fuzz by replaying multiple times and checking consistency.
        // But the safest: we bound seed to a uint8 and use it to decide times to call, but we still need to check pot after each call.
        // Here we will call play() once, then check that after play(), if pot == 0 then it's correct; if pot != 0 then pot == 10 (since before it was 0 and after lose it's 10).
        // Actually, after a loss, pot = 0 + 10 = 10; after a win, pot should be 0 in reference, but bug gives pot = 10 - 1 = 9.
        // So we can assert: after play(), pot == 0 or pot == 10. That fails on bug because pot could be 9.
        // But is this general? Yes: starting from pot=0, after any single play() call, pot must be either 0 (win) or 10 (lose). The bug allows pot=9, breaking the rule.
        // For multiple calls, the rule becomes more complex, but we can restrict to first call only using a flag.
        // However, the instruction says to drive through play() and use fuzz parameters. So we'll call play() once and assert.
        vm.assume(seed < 1000); // any value works
        vm.deal(address(this), 10 ether);
        vm.deal(address(c), 0);
        c.play{value: 10}();
        uint256 afterPot = c.pot();
        assertTrue(afterPot == 0 || afterPot == 10);
    }
}

